// Practical assessment bank — one task per lesson. Each reference solution is verified by
// the in-app Diagnostics runner (Settings → Diagnostics) to score 100% with the grader.
import type { TaskDef, LogicTest, UiTest, Step } from '../engine/harness';

export const M = "import 'package:flutter/material.dart';\n\n";
export const appWrap = (home: string, extra = '') => `${M}void main() {\n  runApp(const MyApp());\n}\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      home: ${home},\n    );\n  }\n}\n${extra}`;
export const scaffold = (body: string, extra = '') => appWrap(`Scaffold(\n        body: ${body},\n      )`, extra);
export const stateful = (name: string, state: string, build: string, extra = '') => appWrap(`const Scaffold(body: ${name}())`, `
class ${name} extends StatefulWidget {
  const ${name}({super.key});

  @override
  State<${name}> createState() => _${name}State();
}

class _${name}State extends State<${name}> {
${state}

  @override
  Widget build(BuildContext context) {
    return ${build};
  }
}
${extra}`);
export const UI_STARTER = scaffold("const Center(child: Text('TODO'))");

type LT = [string, string];
const tasks: TaskDef[] = [];
function L(n: number, title: string, sig: string, statement: string, solution: string, tests: LT[], hint: string, opts: { starter?: string; imports?: string; fn?: string } = {}) {
  const fn = opts.fn ?? sig.match(/(\w+)\s*(<[^>]*>)?\s*\(/)?.[1] ?? sig;
  const imports = opts.imports ? opts.imports + '\n\n' : '';
  tasks[n - 1] = {
    id: 't' + n, title, kind: 'logic', fn, statement,
    expected: tests.slice(0, 3).map(([e, x]) => `${e} → ${x}`).join('; '),
    io: sig, constraints: 'Pure Dart in the supported subset. Do not print the answer — return it.',
    allowed: 'Dart core types, collections, control flow, functions and classes' + (opts.imports ? ` plus ${opts.imports}` : ''),
    starter: opts.starter ?? `${imports}${sig} {\n  // TODO: implement\n  throw UnimplementedError();\n}\n`,
    solution: imports + solution + (opts.starter && opts.starter.includes('// Used by the tests') ? '\n\n' + opts.starter.slice(opts.starter.indexOf('// Used by the tests')) : ''), hints: [hint],
    tests: tests.map(([expr, expect]): LogicTest => ({ expr, expect })),
  };
}
function U(n: number, title: string, statement: string, solution: string, tests: [string, Step[]][], hint: string, starter = UI_STARTER) {
  tasks[n - 1] = {
    id: 't' + n, title, kind: 'ui', statement,
    expected: tests.map(([nm]) => nm).join('; '),
    io: 'A complete Flutter program whose main() calls runApp().', constraints: 'Use only widgets from the preview allow-list (see Code Lab → Supported).',
    allowed: 'Supported Flutter widgets, StatelessWidget, StatefulWidget/setState',
    starter, solution, hints: [hint], tests: tests.map(([name, steps]): UiTest => ({ name, steps })),
  };
}

