L(91, 'Atomic transfer', 'Map<String, int> transfer(Map<String, int> accounts, String from, String to, int amount)', 'Return a new map with amount moved; if either account is missing or funds are insufficient, return an unchanged copy (all-or-nothing).', 'Map<String, int> transfer(Map<String, int> accounts, String from, String to, int amount) {\n  final next = Map<String, int>.from(accounts);\n  final balance = next[from];\n  if (balance == null || !next.containsKey(to) || amount <= 0 || balance < amount) return next;\n  next[from] = balance - amount;\n  next[to] = next[to]! + amount;\n  return next;\n}',
  [["transfer({'a': 10, 'b': 0}, 'a', 'b', 4)", '{a: 6, b: 4}'], ["transfer({'a': 3, 'b': 0}, 'a', 'b', 4)", '{a: 3, b: 0}'], ["transfer({'a': 3}, 'a', 'z', 1)", '{a: 3}']], 'Validate everything first, then apply both writes together.');
L(92, 'Mask a secret', 'String mask(String secret)', "Replace all but the last 4 characters with '*'. Secrets of 4 or fewer characters become all '*'.", "String mask(String secret) {\n  if (secret.length <= 4) return '*' * secret.length;\n  return '*' * (secret.length - 4) + secret.substring(secret.length - 4);\n}",
  [["mask('1234567890')", '******7890'], ["mask('abc')", '***'], ["mask('')", '']], 'Never log or display full secrets.');
L(93, 'Build a URL', 'String buildUrl(String base, String path, Map<String, String> query)', "Join base and path with exactly one '/', then append ?k=v&k2=v2 in insertion order (no '?' when query is empty).", "String buildUrl(String base, String path, Map<String, String> query) {\n  final b = base.endsWith('/') ? base.substring(0, base.length - 1) : base;\n  final p = path.startsWith('/') ? path : '/$path';\n  if (query.isEmpty) return '$b$p';\n  final qs = query.entries.map((e) => '${e.key}=${e.value}').join('&');\n  return '$b$p?$qs';\n}",
  [["buildUrl('https://api.x.com/', '/users', {})", 'https://api.x.com/users'], ["buildUrl('https://api.x.com', 'items', {'page': '2', 'q': 'a'})", 'https://api.x.com/items?page=2&q=a']], 'Normalise slashes before joining.');
